/**
 * Every Cypher statement Backtrack runs, as named, typed functions.
 *
 * Why one file: the README and `graph/queries.cypher` (generated by `pnpm gen:queries`) embed
 * exactly these texts, so what a judge reads is what runs. Each definition carries an `answers:`
 * line (the question it answers or, for writes, what it records), every value is a parameter, and
 * the only interpolation is a clamped `depth()` literal (variable-length bounds cannot be
 * parameters in FalkorDB, see docs/spike-results.md). Every call returns `QueryResult`
 * (rows + cypher + params + ms), which is how the UI shows the evidence behind each claim.
 *
 * Sections: S schema/meta · W world · R recording · P plans/policies · V views for the UI ·
 * Q the catalogue from docs/PLAN.md §5.
 */
import type { QueryResult } from '../contracts/types.js';
import type { TenantGraph } from './client.js';
import { cypher, type Depth, depth, fragment, MAX_DEPTH, toParams } from './cypher.js';

export const DEFAULT_DEPTH = 5;

export interface QueryDef {
  /** Stable id: Q1–Q15 for the catalogue, S/W/R/P/V-numbers for plumbing. */
  id: string;
  title: string;
  answers: string;
  mode: 'read' | 'write';
  /** True when the text contains a variable-length bound taken from `depth`. */
  usesDepth: boolean;
  text: (d: Depth) => string;
}

export type Query<P, R> = ((
  g: TenantGraph,
  params: P,
  opts?: { depth?: number },
) => Promise<QueryResult<R>>) & {
  def: QueryDef;
};

/** All definitions in declaration order; `scripts/gen-queries.ts` prints them. */
export const registry: QueryDef[] = [];

function define<P extends object, R>(spec: {
  id: string;
  title: string;
  answers: string;
  mode: 'read' | 'write';
  text: string | ((d: Depth) => string);
}): Query<P, R> {
  const def: QueryDef = {
    ...spec,
    usesDepth: typeof spec.text === 'function',
    text: typeof spec.text === 'function' ? spec.text : () => spec.text as string,
  };
  registry.push(def);
  const run = (g: TenantGraph, params: P, opts?: { depth?: number }) => {
    const text = def.text(depth(opts?.depth ?? DEFAULT_DEPTH));
    const p = toParams(params as Record<string, unknown>);
    return def.mode === 'read' ? g.read<R>(text, p) : g.write<R>(text, p);
  };
  return Object.assign(run, { def });
}

// Shared fragment: a dependent that is still live, an original action ("do"), and changed
// something. Read-only actions can depend on others but have nothing to undo.
const LIVE_DEPENDENT = fragment(
  `d.kind = 'do' AND all(n IN tail(nodes(p)) WHERE n.status = 'done') AND (d)-[:CAUSED]->(:Effect)`,
);

