export const compensations = define<{ actionId: string }, { n: number }>({
  id: 'P7',
  title: 'Already compensated?',
  answers: 'has an undo or mitigation action already been recorded for this original (UNDOES)?',
  mode: 'read',
  text: `MATCH (:Action)-[u:UNDOES]->(:Action {id: $actionId})
WHERE ID(u) >= 0
RETURN count(u) AS n`,
});

export const createPolicy = define<
  {
    policyId: string;
    userId: string;
    rule: string;
    kind: 'block' | 'confirm' | 'warn';
    tool: string | null;
    agentId: string | null;
    entityType: string | null;
    entityKey: string | null;
    createdFromPlanId: string | null;
    ts: number;
  },
  { id: string }
>({
  id: 'P5',
  title: 'Set a policy',
  answers:
    'records a "never again" rule, who set it, which agent and entity it applies to, and which plan prompted it',
  mode: 'write',
  text: `MATCH (u:User {id: $userId})
CREATE (u)-[:SET {ts: $ts}]->(pol:Policy {id: $policyId, rule: $rule, kind: $kind, tool: $tool,
  created_from_plan_id: $createdFromPlanId, ts: $ts})
WITH pol
OPTIONAL MATCH (ag:Agent {id: $agentId})
FOREACH (x IN CASE WHEN ag IS NULL THEN [] ELSE [ag] END | CREATE (pol)-[:ON_TOOL]->(x))
WITH pol
OPTIONAL MATCH (e:Entity {type: $entityType, key: $entityKey})
FOREACH (x IN CASE WHEN e IS NULL THEN [] ELSE [e] END | CREATE (pol)-[:APPLIES_TO]->(x))
RETURN pol.id AS id`,
});

export const markBlocked = define<
  { policyId: string; actionId: string; ts: number },
  { id: string }
>({
  id: 'P6',
  title: 'Record a blocked action',
  answers: 'records which policy stopped which action',
  mode: 'write',
  text: `MATCH (pol:Policy {id: $policyId}), (a:Action {id: $actionId})
CREATE (pol)-[:BLOCKED {ts: $ts}]->(a)
RETURN a.id AS id`,
});

// ---------------------------------------------------------------------------------------------
// V — views for the UI and the agents
// ---------------------------------------------------------------------------------------------

export interface ActionRow {
  id: string;
  seq: number;
  tool: string;
  args: string;
  result: string | null;
  ts: number;
  kind: string;
  status: string;
  reversible: boolean;
  inverseTool: string | null;
  mitigationTool: string | null;
  runId: string;
  stepId: string;
  agentId: string;
}

const ACTION_COLUMNS = `a.id AS id, a.seq AS seq, a.tool AS tool, a.args AS args, a.result AS result,
  a.ts AS ts, a.kind AS kind, a.status AS status, a.reversible AS reversible,
  a.inverse_tool AS inverseTool, a.mitigation_tool AS mitigationTool,
  r.id AS runId, s.id AS stepId, ag.id AS agentId`;

export const listActions = define<Record<string, never>, ActionRow>({
  id: 'V1',
  title: 'Action list',
  answers: 'which actions have been recorded, in order, by which agent?',
  mode: 'read',
  text: `MATCH (ag:Agent)-[:RAN]->(r:Run)-[:HAS]->(s:Step)-[:DID]->(a:Action)
RETURN ${ACTION_COLUMNS}
ORDER BY seq`,
});

export const getActions = define<{ ids: string[] }, ActionRow>({
  id: 'V2',
  title: 'Actions by id',
  answers: 'what exactly are these recorded actions?',
  mode: 'read',
  text: `MATCH (ag:Agent)-[:RAN]->(r:Run)-[:HAS]->(s:Step)-[:DID]->(a:Action)
WHERE a.id IN $ids
RETURN ${ACTION_COLUMNS}
ORDER BY seq`,
});

export const graphNodes = define<
  Record<string, never>,
  { id: string; label: string; props: Record<string, unknown> }
>({
  id: 'V3',
  title: 'Graph snapshot: nodes',
  answers:
    'which actions, touched entities, agents, runs, plans, policies and users should the graph view draw?',
  mode: 'read',
  // Seeded entities nobody has touched are left out: they are world, not history.
  text: `MATCH (n)
WHERE (n:Action OR n:Agent OR n:Run OR n:UndoPlan OR n:Policy OR n:User)
   OR (n:Entity AND ((n)<-[:READ]-() OR (n)<-[:ON]-()))
WITH n, labels(n)[0] AS label
OPTIONAL MATCH (ag:Agent)-[:RAN]->(r:Run)-[:HAS]->(:Step)-[:DID]->(n)
RETURN CASE WHEN label = 'Entity' THEN n.type + ':' + n.key ELSE n.id END AS id, label,
  {tool: n.tool, status: n.status, kind: n.kind, seq: n.seq, reversible: n.reversible,
   name: n.name, display: n.display, rule: n.rule, goal: n.goal, summary: n.summary,
   agentId: coalesce(ag.id, n.agent_id), runId: r.id} AS props`,
});

export const graphLinks = define<
  Record<string, never>,
  { source: string; target: string; type: string; order: number | null }
>({
  id: 'V4',
  title: 'Graph snapshot: links',
  answers:
    'how are those nodes connected (Steps and Effects collapsed so an action links straight to its run and entities)?',
  mode: 'read',
  text: `MATCH (a:Action)-[:CAUSED]->(:Effect)-[:ON]->(e:Entity)
RETURN DISTINCT a.id AS source, e.type + ':' + e.key AS target, 'CAUSED' AS type, null AS order
UNION
MATCH (a:Action)-[:READ]->(e:Entity)
RETURN a.id AS source, e.type + ':' + e.key AS target, 'READ' AS type, null AS order
UNION
MATCH (r:Run)-[:HAS]->(:Step)-[:DID]->(a:Action)
RETURN r.id AS source, a.id AS target, 'DID' AS type, null AS order
UNION
MATCH (x)-[rel:DEPENDS_ON|UNDOES|RAN|ROOT|REVERTS|COULD_NOT_REVERT|CONFLICT|APPROVED|DENIED|REQUESTED|SET|ON_TOOL|BLOCKED]->(y)
WHERE NOT x:Entity AND NOT y:Entity
RETURN x.id AS source, y.id AS target, type(rel) AS type, rel.order AS order
UNION
MATCH (pol:Policy)-[:APPLIES_TO]->(e:Entity)
RETURN pol.id AS source, e.type + ':' + e.key AS target, 'APPLIES_TO' AS type, null AS order`,
});

// ---------------------------------------------------------------------------------------------
// Q — the catalogue (docs/PLAN.md §5)
// ---------------------------------------------------------------------------------------------

export interface ClosureRow {
  id: string;
  tool: string;
  seq: number;
  agentId: string;
  runId: string;
  reversible: boolean;
  inverseTool: string | null;
  mitigationTool: string | null;
  hops: number;
  via: string[];
  viaIds: string[];
}

export const q1Downstream = define<{ actionId: string }, ClosureRow>({
  id: 'Q1',
  title: 'Downstream closure with paths',
  answers:
    'if I undo this action, which later actions depend on it (transitively, up to depth N), how many hops away, and through which actions?',
  mode: 'read',
  // Shortest path per dependent: ORDER BY length then head(collect()).
  text: (d) => cypher`MATCH p = (root:Action {id: $actionId})<-[:DEPENDS_ON*1..${d}]-(d:Action)
WHERE ${LIVE_DEPENDENT}
WITH d, p ORDER BY length(p)
WITH d, head(collect(p)) AS p
MATCH (ag:Agent)-[:RAN]->(run:Run)-[:HAS]->(:Step)-[:DID]->(d)
RETURN d.id AS id, d.tool AS tool, d.seq AS seq, ag.id AS agentId, run.id AS runId,
  d.reversible AS reversible, d.inverse_tool AS inverseTool, d.mitigation_tool AS mitigationTool,
  length(p) AS hops, [n IN nodes(p) | n.tool] AS via, [n IN nodes(p) | n.id] AS viaIds
ORDER BY seq DESC`,
});

export interface UndoOrderRow {
  id: string;
  tool: string;
  seq: number;
  status: string;
  reversible: boolean;
  inverseTool: string | null;
  mitigationTool: string | null;
  entities: Array<{ type: string; key: string; display: string | null; kind: string }>;
}

export const q2UndoOrder = define<{ actionIds: string[] }, UndoOrderRow>({
  id: 'Q2',
  title: 'Undo plan order',
  answers:
    'in what order can these actions be undone, and what did each one change? (seq DESC is a reverse topological order because DEPENDS_ON always points to a smaller seq)',
  mode: 'read',
  text: `MATCH (a:Action)
WHERE a.id IN $actionIds
OPTIONAL MATCH (a)-[:CAUSED]->(f:Effect)-[:ON]->(e:Entity)
WITH a, f, e ORDER BY f.id
WITH a, [x IN collect({type: e.type, key: e.key, display: e.display, kind: f.kind}) WHERE x.key IS NOT NULL] AS entities
RETURN a.id AS id, a.tool AS tool, a.seq AS seq, a.status AS status, a.reversible AS reversible,
  a.inverse_tool AS inverseTool, a.mitigation_tool AS mitigationTool, entities
ORDER BY seq DESC`,
});

export const q3BlastRadius = define<
  { actionId: string },
  { actions: number; irreversible: number; entities: string[] }
>({
  id: 'Q3',
  title: 'Blast radius summary',
  answers:
    'how big is undoing this action: how many actions, how many of them irreversible, which entities?',
  mode: 'read',
  text: (d) => cypher`MATCH (root:Action {id: $actionId})
OPTIONAL MATCH p = (root)<-[:DEPENDS_ON*1..${d}]-(d:Action)
WHERE ${LIVE_DEPENDENT}
WITH root, collect(DISTINCT d) AS dependents
UNWIND [root] + dependents AS a
OPTIONAL MATCH (a)-[:CAUSED]->(:Effect)-[:ON]->(e:Entity)
RETURN count(DISTINCT a) AS actions,
  count(DISTINCT CASE WHEN a.reversible = false THEN a.id END) AS irreversible,
  collect(DISTINCT e.type + ':' + e.key) AS entities`,
});

export const q4LockIn = define<{ actionId: string }, { id: string; tool: string; seq: number }>({
  id: 'Q4',
  title: 'Gate: what an irreversible action would lock in',
  answers:
    'which reversible changes does this pending irreversible action build on, so that doing it would make them impossible to undo cleanly?',
  mode: 'read',
  text: () => cypher`MATCH (pending:Action {id: $actionId})-[:DEPENDS_ON*1..${depth(MAX_DEPTH)}]->(u:Action)
WHERE u.status = 'done' AND u.kind = 'do' AND u.reversible = true AND (u)-[:CAUSED]->(:Effect)
RETURN DISTINCT u.id AS id, u.tool AS tool, u.seq AS seq
ORDER BY seq`,
});

export const q5Policies = define<
  { tool: string; agentId: string; entities: string[] },
  { id: string; rule: string; kind: 'block' | 'confirm' | 'warn'; ts: number; scope: string[] }
>({
  id: 'Q5',
  title: 'Policy check',
  answers:
    'does any policy block, require confirmation for, or warn about this call: this tool, or any tool on these entities, for this agent?',
  mode: 'read',
  text: `MATCH (pol:Policy)
WHERE (pol.tool = $tool OR (pol.tool IS NULL AND (pol)-[:APPLIES_TO]->(:Entity)))
  AND (NOT (pol)-[:ON_TOOL]->(:Agent) OR (pol)-[:ON_TOOL]->(:Agent {id: $agentId}))
OPTIONAL MATCH (pol)-[:APPLIES_TO]->(e:Entity)
WITH pol, collect(e.type + ':' + e.key) AS scope
WHERE size(scope) = 0 OR any(k IN scope WHERE k IN $entities)
RETURN pol.id AS id, pol.rule AS rule, pol.kind AS kind, pol.ts AS ts, scope,
  CASE pol.kind WHEN 'block' THEN 0 WHEN 'confirm' THEN 1 ELSE 2 END AS rank
ORDER BY rank, ts`,
});

export interface ExplainRow {
  id: string;
  seq: number;
  tool: string;
  args: string;
  result: string | null;
  ts: number;
  kind: string;
  status: string;
  reversible: boolean;
  inverseTool: string | null;
  mitigationTool: string | null;
  runId: string;
  stepId: string;
  agentId: string;
  thought: string | null;
  reads: Array<{
    entity: string;
    writerId: string | null;
    writerTool: string | null;
    writerSeq: number | null;
    field: string | null;
    after: string | null;
  }>;
  effects: Array<{
    id: string | null;
    kind: string | null;
    field: string | null;
    before: string | null;
    after: string | null;
    ts: number | null;
    type: string | null;
    key: string | null;
    display: string | null;
  }>;
  dependsOn: Array<{ actionId: string; tool: string; seq: number }>;
  dependedOnBy: Array<{ actionId: string; tool: string; seq: number }>;
}

export const q6Explain = define<{ actionId: string }, ExplainRow>({
  id: 'Q6',
  title: 'Explain an action',
  answers:
    'why did this action happen, what did it read and who wrote that, what did it change, and what depends on it?',
  mode: 'read',
  text: `MATCH (ag:Agent)-[:RAN]->(r:Run)-[:HAS]->(s:Step)-[:DID]->(a:Action {id: $actionId})
OPTIONAL MATCH (a)-[:READ]->(re:Entity)
OPTIONAL MATCH (re)<-[:ON]-(rf:Effect)<-[:CAUSED]-(w:Action)
WHERE w.seq < a.seq
WITH ag, r, s, a, re, rf, w ORDER BY w.seq DESC
WITH ag, r, s, a, re, head(collect({id: w.id, tool: w.tool, seq: w.seq, field: rf.field, after: rf.after})) AS wr
WITH ag, r, s, a, [x IN collect({entity: re.type + ':' + re.key, writerId: wr.id, writerTool: wr.tool,
  writerSeq: wr.seq, field: wr.field, after: wr.after}) WHERE x.entity IS NOT NULL] AS reads
OPTIONAL MATCH (a)-[:CAUSED]->(f:Effect)-[:ON]->(e:Entity)
WITH ag, r, s, a, reads, f, e ORDER BY f.id
WITH ag, r, s, a, reads, [x IN collect({id: f.id, kind: f.kind, field: f.field, before: f.before,
  after: f.after, ts: f.ts, type: e.type, key: e.key, display: e.display}) WHERE x.id IS NOT NULL] AS effects
OPTIONAL MATCH (a)-[:DEPENDS_ON]->(up:Action)
WITH ag, r, s, a, reads, effects,
  [u IN collect(DISTINCT up) | {actionId: u.id, tool: u.tool, seq: u.seq}] AS dependsOn
OPTIONAL MATCH (down:Action)-[:DEPENDS_ON]->(a)
WITH ag, r, s, a, reads, effects, dependsOn,
  [x IN collect(DISTINCT down) | {actionId: x.id, tool: x.tool, seq: x.seq}] AS dependedOnBy
RETURN a.id AS id, a.seq AS seq, a.tool AS tool, a.args AS args, a.result AS result, a.ts AS ts,
  a.kind AS kind, a.status AS status, a.reversible AS reversible, a.inverse_tool AS inverseTool,
  a.mitigation_tool AS mitigationTool, r.id AS runId, s.id AS stepId, ag.id AS agentId,
  s.thought AS thought, reads, effects, dependsOn, dependedOnBy`,
});

export const q7CrossAgent = define<
  { actionId: string },
  { agentId: string; actionId: string; tool: string; hops: number }
>({
  id: 'Q7',
  title: 'Cross-agent dependents',
  answers:
    "which other agents' actions depend on this one (through Step, Run and Agent), and how far away are they?",
  mode: 'read',
  text: (
    d,
  ) => cypher`MATCH (rag:Agent)-[:RAN]->(:Run)-[:HAS]->(:Step)-[:DID]->(root:Action {id: $actionId})
MATCH p = (root)<-[:DEPENDS_ON*1..${d}]-(d:Action)
WHERE ${LIVE_DEPENDENT}
MATCH (ag:Agent)-[:RAN]->(:Run)-[:HAS]->(:Step)-[:DID]->(d)
WHERE ag.id <> rag.id
RETURN ag.id AS agentId, d.id AS actionId, d.tool AS tool, min(length(p)) AS hops
ORDER BY hops, actionId`,
});

export const q12EntityHistory = define<
  { type: string; key: string },
  {
    seq: number;
    actionId: string;
    tool: string;
    kind: string;
    status: string;
    field: string | null;
    before: string;
    after: string;
    ts: number;
    runId: string;
    agentId: string;
  }
>({
  id: 'Q12',
  title: 'Entity history across runs and agents',
  answers: 'who changed this entity, when, in which run, from what to what?',
  mode: 'read',
  text: `MATCH (e:Entity {type: $type, key: $key})<-[:ON]-(f:Effect)<-[:CAUSED]-(a:Action)
MATCH (ag:Agent)-[:RAN]->(r:Run)-[:HAS]->(:Step)-[:DID]->(a)
RETURN a.seq AS seq, a.id AS actionId, a.tool AS tool, a.kind AS kind, a.status AS status,
  f.field AS field, f.before AS before, f.after AS after, f.ts AS ts, r.id AS runId, ag.id AS agentId
ORDER BY seq, actionId`,
});

export const q13Recall = define<
  { actionId: string | null; tool: string | null; type: string | null; key: string | null },
  {
    kind: 'plan' | 'policy';
    id: string;
    ts: number;
    status: string;
    summary: string;
    actionId: string | null;
    tool: string | null;
  }
>({
  id: 'Q13',
  title: 'Recall',
  answers:
    'have we undone this action, this tool, or changes to this entity before, and is there a policy about it? (with dates)',
  mode: 'read',
  text: `MATCH (plan:UndoPlan)-[:ROOT]->(root:Action)
WHERE root.id = $actionId OR root.tool = $tool
   OR (plan)-[:REVERTS|COULD_NOT_REVERT]->(:Action {id: $actionId})
   OR (root)-[:CAUSED]->(:Effect)-[:ON]->(:Entity {type: $type, key: $key})
RETURN 'plan' AS kind, plan.id AS id, plan.ts AS ts, plan.status AS status, plan.summary AS summary,
  root.id AS actionId, root.tool AS tool
UNION
MATCH (pol:Policy)
WHERE pol.tool = $tool OR (pol)-[:APPLIES_TO]->(:Entity {type: $type, key: $key})
RETURN 'policy' AS kind, pol.id AS id, pol.ts AS ts, pol.kind AS status, pol.rule AS summary,
  null AS actionId, pol.tool AS tool`,
});

export interface AlgoActionRow {
  id: string;
  tool: string;
  seq: number;
  status: string;
  agentId: string | null;
  score: number;
}

export const q8LoadBearing = define<{ limit: number }, AlgoActionRow>({
  id: 'Q8',
  title: 'Load-bearing actions (PageRank)',
  answers:
    'which actions does the most other work rest on? (PageRank over DEPENDS_ON: rank flows from dependents to what they depend on)',
  mode: 'read',
  text: `CALL algo.pageRank('Action', 'DEPENDS_ON') YIELD node, score
WITH node, score WHERE node.kind = 'do'
OPTIONAL MATCH (ag:Agent)-[:RAN]->(:Run)-[:HAS]->(:Step)-[:DID]->(node)
RETURN node.id AS id, node.tool AS tool, node.seq AS seq, node.status AS status, ag.id AS agentId, score
ORDER BY score DESC, seq
LIMIT $limit`,
});

export const q9Hinges = define<{ limit: number }, AlgoActionRow>({
  id: 'Q9',
  title: 'Hinge actions (betweenness)',
  answers:
    'which actions sit on the most dependency paths between other actions, so that undoing them splits the history?',
  mode: 'read',
  // Betweenness samples source nodes by default, so the same graph can rank differently from
  // call to call (spike-results.md). A sample far larger than any history, with a fixed seed,
  // makes the ranking repeatable: the hinge a person is shown does not change on refresh.
  text: `CALL algo.betweenness({nodeLabels: ['Action'], relationshipTypes: ['DEPENDS_ON'],
  samplingSize: 10000, samplingSeed: 7}) YIELD node, score
WITH node, score WHERE node.kind = 'do'
OPTIONAL MATCH (ag:Agent)-[:RAN]->(:Run)-[:HAS]->(:Step)-[:DID]->(node)
RETURN node.id AS id, node.tool AS tool, node.seq AS seq, node.status AS status, ag.id AS agentId, score
ORDER BY score DESC, seq
LIMIT $limit`,
});

export const q10Clusters = define<
  Record<string, never>,
  { componentId: number; size: number; actions: Array<{ id: string; tool: string; seq: number }> }
>({
  id: 'Q10',
  title: 'Independent clusters (weakly connected components)',
  answers:
    'which groups of actions are independent of each other, so that undoing one group cannot touch another?',
  mode: 'read',
  text: `CALL algo.wcc({nodeLabels: ['Action'], relationshipTypes: ['DEPENDS_ON']}) YIELD node, componentId
WITH componentId, node ORDER BY node.seq
WITH componentId, collect({id: node.id, tool: node.tool, seq: node.seq}) AS actions
RETURN componentId, size(actions) AS size, actions
ORDER BY size DESC, componentId`,
});

export const q11PathBetween = define<
  { from: string; to: string },
  { ids: string[]; tools: string[]; pathWeight: number }
>({
  id: 'Q11',
  title: 'Dependency path between two actions (SPpaths)',
  answers:
    'how does a later action depend on an earlier one: the shortest DEPENDS_ON route from the earlier action to the later?',
  mode: 'read',
  // 'incoming' walks from the earlier action against the DEPENDS_ON arrows to the later one.
  text: `MATCH (s:Action {id: $from}), (t:Action {id: $to})
CALL algo.SPpaths({sourceNode: s, targetNode: t, relTypes: ['DEPENDS_ON'], weightProp: 'weight',
  relDirection: 'incoming', pathCount: 1, maxLen: 10})
YIELD path, pathWeight
RETURN [n IN nodes(path) | n.id] AS ids, [n IN nodes(path) | n.tool] AS tools, pathWeight`,
});

export const q15PlanEntities = define<
  { planId: string },
  { type: string; key: string; state: string | null }
>({
  id: 'Q15',
  title: 'Rehearsal diff: entity states a plan touches',
  answers:
    'what state is every entity this plan touches in, in this graph? Run on the live graph and on the GRAPH.COPY fork after the rehearsal; the difference is the diff.',
  mode: 'read',
  text: `MATCH (:UndoPlan {id: $planId})-[:REVERTS|COULD_NOT_REVERT]->(a:Action)
OPTIONAL MATCH (a)-[:CAUSED]->(:Effect)-[:ON]->(e1:Entity)
OPTIONAL MATCH (a)<-[:UNDOES]-(:Action)-[:CAUSED]->(:Effect)-[:ON]->(e2:Entity)
WITH collect(DISTINCT e1) + collect(DISTINCT e2) AS touched
UNWIND touched AS e
RETURN DISTINCT e.type AS type, e.key AS key, e.state AS state
ORDER BY type, key`,
});

export interface ConflictRow {
  effectId: string;
  kind: string;
  field: string | null;
  before: string;
  after: string;
  type: string;
  key: string;
  display: string | null;
  state: string | null;
  laterWriters: Array<{ id: string; tool: string; seq: number }>;
}

export const q14Conflicts = define<{ actionId: string }, ConflictRow>({
  id: 'Q14',
  title: 'Conflict check',
  answers:
    'is each entity this action changed still exactly as the action left it (Entity.state vs Effect.after), and if not, which later live action wrote it?',
  mode: 'read',
  text: `MATCH (a:Action {id: $actionId})-[:CAUSED]->(f:Effect)-[:ON]->(e:Entity)
OPTIONAL MATCH (e)<-[:ON]-(:Effect)<-[:CAUSED]-(later:Action)
WHERE later.seq > a.seq AND later.status = 'done'
WITH f, e, [w IN collect(DISTINCT later) | {id: w.id, tool: w.tool, seq: w.seq}] AS laterWriters
RETURN f.id AS effectId, f.kind AS kind, f.field AS field, f.before AS before, f.after AS after,
  e.type AS type, e.key AS key, e.display AS display, e.state AS state, laterWriters
ORDER BY effectId`,
});
